    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Find maximal straight runs of 5. An attached colored strip at one end
    # supplies a repeating pattern that is extended along the 5-run.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c + 1 < w and grid[r][c + 1] == 5:
                c += 1
            if c > a:
                runs.append(("h", r, a, c))
            c += 1
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r + 1 < h and grid[r + 1][c] == 5:
                r += 1
            if r > a:
                runs.append(("v", c, a, r))
            r += 1

    for orient, fixed, start, end in runs:
        if orient == "v":
            col, r0, r1 = fixed, start, end
            # Seed is a sequence of one or more adjacent colored rows at an
            # endpoint, each carrying a horizontal motif to the right.
            for direction in (-1, 1):
                endpoint = r1 if direction == -1 else r0
                seed_rows = []
                rr = endpoint
                step = direction
                while r0 <= rr <= r1:
                    cc = col + 1
                    rowpat = []
                    while cc < w and grid[rr][cc] not in (0, 5):
                        rowpat.append(grid[rr][cc])
                        cc += 1
                    if not rowpat:
                        break
                    seed_rows.append(rowpat)
                    rr += step
                if seed_rows:
                    # seed_rows order follows outward-to-inward traversal;
                    # repeat from the matching endpoint into the 5-run.
                    period = len(seed_rows)
                    ordered = seed_rows[::-1] if direction == -1 else seed_rows
                    for offset, rr in enumerate(range(r0, r1 + 1)):
                        pat = ordered[offset % period]
                        for j, color in enumerate(pat, start=col + 1):
                            if j < w and out[rr][j] == 0:
                                out[rr][j] = color
                    break
        else:
            row, c0, c1 = fixed, start, end
            # Seed is a vertical strip attached below/above an endpoint;
            # repeat its color sequence across the horizontal 5-run.
            for direction in (1, -1):
                endpoint = c0 if direction == 1 else c1
                seed = []
                rr = row + 1
                while rr < h and grid[rr][endpoint] not in (0, 5):
                    seed.append(grid[rr][endpoint])
                    rr += 1
                if seed:
                    for cc in range(c0, c1 + 1):
                        for k, color in enumerate(seed, start=row + 1):
                            if k < h and out[k][cc] == 0:
                                out[k][cc] = color
                    break
    return out
